        JZ ACQ_START
        CALL X_1DBD

; ACQ_START: (re)start master acquisition. Reached again whenever tracking is lost.
ACQ_START:
        CALL CPY_GRI_TO_TOA
        LXI H,CUR_TOA
        CALL TOA_TO_BIN
        SUI 05H
        STA WIN_END
        MVI A,0EH
        CALL X_0DB3
        LXI H,CUR_REC
        LXI B,REC_MASTER
        CALL COPY4
        LXI H,BCD_K_00080980
        CALL TOA_ADD_CONST
        MVI A,0EH
        CALL X_0DB3
        LXI H,CUR_REC
        LXI B,REC_SEC
        CALL COPY4
SEARCH_RESTART:
        CALL RESET_PULSES
        LXI B,REC_MASTER

