        MOV H,B
        MOV L,C
        INX H
        INX H
        INX H
        INX H
        INX H
        INR M
        PUSH PSW
        LDA SW_D1
        CPI 0AH
        JNZ L_096E
        POP PSW
        MOV A,M
        CPI 64H                     ; 'd'
        JMP L_0972
L_096E:
        POP PSW
        MOV A,M
        CPI 0AH
L_0972:
        JNZ L_09CB
        MVI M,00H
        PUSH B
