        ANI 80H
        RLC
        RLC
        RLC
        ORA D
        MOV D,A
        LDA CUR_REC
        ANI 20H                     ; ' '
        CPI 20H                     ; ' '
        MVI A,08H
        JNZ L_0A14
        LDA REC_MASTER
        RRC
        RRC
        ANI 08H
L_0A14:
