; PULSE_SCORE_UPDATE (was SUB_0B07). Starting from CUR_NPULSE, walks all 8 bits of
; PHASE_CODE (a per-bit RRC over 8 iterations): for each mismatch bit (PHASE_CODE bit=1,
; since PHASE_CODE is already an XOR-vs-reference result) adds CUR_MODE to a running
; score, for each match bit subtracts it, then stores the score back into CUR_NPULSE.
; If the score goes negative (bit 7 set), corrects it by adding VAR_6FE7 (up to twice)
; and applies a matching -1-pulse TOA adjustment via CALC_TD/TOA_SUB_CONST each time
; (mirrors the positive-side path with CALC_TD/TOA_ADD_CONST, not yet traced in as much
; detail). Reads as a mismatch-weighted confidence score with automatic pulse-index
; correction on underflow, but the good/bad direction of the score and VAR_6FE7's exact
; role aren't fully pinned down - medium confidence only.
PULSE_SCORE_UPDATE:
        LXI H,CUR_PULSE_PTR
        INR M
        LXI H,CUR_MODE
        LDA CUR_NPULSE
        MOV B,A
        LDA PHASE_CODE
        MVI E,08H
L_0B17:
        RRC
        MOV C,A
        MOV A,B
        JC L_0B21
        SUB M
        JMP L_0B22
L_0B21:
        ADD M
L_0B22:
        MOV B,A
        MOV A,C
        DCR E
        JNZ L_0B17
        LDA VAR_6FE7
        MOV C,A
        LXI H,CUR_NPULSE
        MOV M,B
        MOV A,B
        RLC
        MOV A,B
        JC L_0B65
        SUB C
        JP L_0B40
        CALL CALC_TD
        JMP L_0B8A
L_0B40:
        MOV M,A
        LXI H,CUR_PULSES
        INR M
        CALL CALC_TD
        CALL TOA_ADD_CONST
        LDA VAR_6FE7
        MOV C,A
        LXI H,CUR_NPULSE
        MOV A,M
        SUB C
        JM L_0B8A
        MOV M,A
        LXI H,VAR_6FE3
        CALL TOA_ADD_CONST
        LXI H,CUR_PULSES
        INR M
        JMP L_0B8A
L_0B65:
        ADD C
        MOV M,A
        LXI H,CUR_PULSES
        DCR M
        CALL CALC_TD
        CALL TOA_SUB_CONST
        LDA VAR_6FE7
        MOV C,A
        LXI H,CUR_NPULSE
        MOV A,M
        RLC
        JNC L_0B8A
        MOV A,M
        ADD C
        MOV M,A
        LXI H,VAR_6FE3
        CALL TOA_SUB_CONST
        LXI H,CUR_PULSES
        DCR M
L_0B8A:
        JMP L_0CFE

; CLAMP_HL_BC (was X_0B8D; the old rom-status.md guess "16-bit arithmetic on HL with
; BC = 1" undersold it). Borrows GRI_SW as scratch storage for the incoming HL (not the
; GRI switch value - just unused RAM at this call site). Uses NEG_HL and a two-sided
; DAD-based comparison between HL and BC to decide a sign, then conditionally returns
; either the original HL unchanged or a negated/adjusted version. Called right after
; POPCOUNT_ADJ_HL with BC = 01FFH (511 - a plain integer constant; the tool's "D_01FF"
; label for this LXI's immediate operand is a labeling artifact, not real data), which
; together with the surrounding code (see PHASE_QUALITY_UPDATE, 0BC5) strongly suggests
; "clamp/limit signed HL to roughly +-511" - a saturating-accumulator helper. The exact
; register choreography (why GRI_SW, why two NEG_HL calls) isn't fully traced.
CLAMP_HL_BC:
        SHLD GRI_SW
        PUSH B
        MVI E,00H
        MOV A,H
        RLC
        CC NEG_HL
        POP B
        PUSH B
        PUSH D
        PUSH H
        MOV H,B
        MOV L,C
        CALL NEG_HL
        POP D
        DAD D
        MOV A,H
        RLC
        LHLD GRI_SW
        POP D
        JC L_0BB3
        POP H
        MOV A,E
        RRC
        CC NEG_HL
        RET
L_0BB3:
        POP B
        RET

; POPCOUNT_ADJ_HL (was SUB_0BB5). A = an 8-bit pattern. For each of its 8 bits
; (successive RRC): INX H if the bit is 1, DCX H if 0. Net effect: HL += 2*popcount(A) - 8.
; Same shape as PULSE_SCORE_UPDATE's per-bit tally but applied to a pointer via INX/DCX
; instead of an accumulator via ADD/SUB M, and with an implicit weight of 1 instead of
; CUR_MODE. Used by PHASE_QUALITY_UPDATE to adjust the two saturating quality
; accumulators by the popcount of PHASE_CODE / PHASE_CODE_HI each epoch.
POPCOUNT_ADJ_HL:
        MVI E,08H
L_0BB7:
        RRC
        JC L_0BBF
        DCX H
        JMP L_0BC0
L_0BBF:
        INX H
L_0BC0:
        DCR E
        JNZ L_0BB7
        RET

; PHASE_QUALITY_UPDATE (was SUB_0BC5, extends through 0C34). Two parallel saturating
; 16-bit accumulators, PHASE_QUAL_A:PHASE_QUAL_A_HI (6FB5:6FB6) and PHASE_QUAL_B:
; PHASE_QUAL_B_HI (6FB8:6FB9), are each adjusted by POPCOUNT_ADJ_HL using PHASE_CODE
; (accumulator A) and PHASE_CODE_HI (accumulator B) as the bit pattern, then clamped via
; CLAMP_HL_BC against +-511 and stored back. If accumulator A's high byte is 0FFH
; (strongly negative) with PHASE_QUAL_A bit 6 clear, or accumulator B's low byte bit 6 is
; set (gated by PHASE_QUAL_A_HI/PHASE_QUAL_B_HI sanity checks and CUR_FLAGS bit 2), sets
; PHASE_QUAL_FLAGS bit 7 or bit 6 and calls PULSE_ALIGN_ADJ2_AND_CLEAR with A=80H or 40H -
; i.e. once a quality accumulator drifts far enough, this triggers a real +-1-pulse TOA
; realignment (PULSE_ALIGN_ADJ2 tests exactly those two bits). This is also confirmed as
; where PHASE_QUAL_FLAGS's bits actually come from - EPOCH_PHASE_UPDATE (0817) reads it
; into PULSE_ALIGN_FLAGS every epoch, and PULSE_ALIGN_ADJ_6FBE/PULSE_ALIGN_ADJ act on
; PULSE_ALIGN_FLAGS's bits 7/6. Also calls SLOTREC_UPDATE when SW_D4 (a thumbwheel digit)
; >= 9, an apparent debug/calibration hook.
PHASE_QUALITY_UPDATE:
        CALL CALC_TD
        LDA SW_D4
        CPI 09H
        CNC SLOTREC_UPDATE
        LXI H,M_6FB0
        INR M
        LHLD PHASE_QUAL_A
        LDA PHASE_CODE
        CALL POPCOUNT_ADJ_HL
        LXI B,D_01FF
        CALL CLAMP_HL_BC
        SHLD PHASE_QUAL_A
        LHLD PHASE_QUAL_B
        LDA PHASE_CODE_HI
        CALL POPCOUNT_ADJ_HL
        LXI B,D_01FF
        CALL CLAMP_HL_BC
        SHLD PHASE_QUAL_B
        LDA PHASE_QUAL_A_HI
        CPI 0FFH
        JNZ L_0C08
        LDA PHASE_QUAL_A
        ANI 40H                     ; '@'
        JZ L_0C24
L_0C08:
        LDA PHASE_QUAL_B_HI
        CPI 00H
        RNZ
        LDA PHASE_QUAL_B
        ANI 40H                     ; '@'
        JNZ L_0C17
        RET
L_0C17:
        LDA CUR_FLAGS
        ANI 04H
        RNZ
        MVI A,80H
        MVI B,40H                   ; '@'
        JMP L_0C2E
L_0C24:
        LDA CUR_FLAGS
        ANI 04H
        RNZ
        MVI A,40H                   ; '@'
        MVI B,80H
L_0C2E:
        LXI H,PHASE_QUAL_FLAGS
        ORA M
        MOV M,A
        MOV A,B
        JMP PULSE_ALIGN_ADJ2_AND_CLEAR
L_0C37:
        CALL PULSE_SCORE_UPDATE
        LXI B,M_8020
        LXI H,CUR_FLAGS
        MOV A,M
        ANI 20H                     ; ' '
        DCX H
        ORA M
        CPI 20H                     ; ' '
        DCX H
        JZ L_0C50
        INR M
        MOV A,M
        CPI 64H                     ; 'd'
        RM
L_0C50:
        MVI M,00H
        INX H
        INX H
        MOV A,M
        ANI 20H                     ; ' '
        RLC
        RLC
        DCX H
        ORA M
        CPI 80H
        JZ L_0CB1
        MVI E,00H
        CPI 81H
        JZ L_0CB0
        INR E
        CPI 00H
        JZ L_0CB0
        INR E
        LXI B,M_2010
        CPI 01H
        JZ L_0C96
        CPI 02H
        JZ L_0CB1
        INX H
        MOV A,M
        ORI 10H
        MOV M,A
        LXI H,CUR_REC
        MOV A,M
        ANI 7FH
        MOV M,A
        LXI H,RESET
        SHLD CUR_PULSE_PTR
        SHLD PHASE_QUAL_A
        SHLD PHASE_QUAL_B
        JMP L_0CB1
L_0C96:
        MVI A,01H
        STA CUR_MODE
        MOV M,E
        CALL MASTER_CORR_ADD_3000
        CALL TOA_ADD_3000
        MVI C,02H

; SET_QUAL_FLAGS (was SUB_0CA4). Clears M_6FB2, ORs C's bits into PHASE_QUAL_FLAGS,
; returns B in A. A small "apply a (status, flag-bits) pair" utility called from the
; CUR_FLAGS/PHASE_CODE decision tree at L_0C37-0C96 (not independently named - it's not
; a call target, just inline flow reached by a jump - but see its shape: it tests CUR_FLAGS
; bits and PHASE_CODE bits 20H/80H to choose which (B,C) pair to hand to SET_QUAL_FLAGS,
; including a full PHASE_QUAL_A/PHASE_QUAL_B/CUR_PULSE_PTR reset for at least one case -
; looks like a fuller quality/lock-state classifier than PHASE_QUALITY_UPDATE alone,
; not traced branch-by-branch).
SET_QUAL_FLAGS:
        XRA A
        STA M_6FB2
        LXI H,PHASE_QUAL_FLAGS
        MOV A,M
        ORA C
        MOV M,A
        MOV A,B
        RET
L_0CB0:
        MOV M,E
L_0CB1:
        CALL SET_QUAL_FLAGS
        RLC
        CALL MASTER_CORR_ADJ
        JC TOA_SUB_6000
        JMP L_0EC7

; MASTER_CORR_ADJ (was SUB_0CBE). Only acts when SLOT_IDX==0 (master): adds
; TOA_ADJ_2000 or subtracts TOA_ADJ_6000 to/from MASTER_TOA_CORR (M_70C3) depending on a
; carry flag passed in from the caller. MASTER_CORR_ADD_3000 (0CE8) is the same shape,
; always adding TOA_ADJ_3000, no carry test. Both correct MASTER_TOA_CORR rather than
; CUR_TOA directly - MASTER_TOA_CORR is the term ACCUM_SLOT_TOA (091B) adds into the
; master's running sum, so these are indirect, master-only pulse-interval corrections
; that only take effect on the next accumulation pass.
MASTER_CORR_ADJ:
        PUSH PSW
        PUSH B
        LXI B,MASTER_TOA_CORR
        JC L_0CD7
        LDA SLOT_IDX
        CPI 00H
        JNZ L_0CFB
        LXI H,TOA_ADJ_2000
        CALL BCD_ADD4
        JMP L_0CFB
L_0CD7:
        LDA SLOT_IDX
        CPI 00H
        JNZ L_0CFB
        LXI H,TOA_ADJ_6000
        CALL BCD_SUB4
        JMP L_0CFB
MASTER_CORR_ADD_3000:
        PUSH PSW
        PUSH B
        LXI B,MASTER_TOA_CORR
        LDA SLOT_IDX
        CPI 00H
        JNZ L_0CFB
        LXI H,TOA_ADJ_3000
        CALL BCD_ADD4
L_0CFB:
        POP B
        POP PSW
        RET
L_0CFE:
        CALL SLOTREC_PHASE
        LDA CUR_REC
        ANI 80H
        JNZ L_0D0C
        CALL SLOTREC_UPDATE
L_0D0C:
        LXI H,M_6FB2
        PUSH H
        MOV A,M
        MVI H,00H
        MOV L,A
        RLC
        JNC L_0D1A
        MVI H,0FFH
L_0D1A:
        LDA PHASE_CODE_HI
        CMA
        CALL POPCOUNT_ADJ_HL
        LXI B,D_005F
        CALL CLAMP_HL_BC
        MOV A,L
        STA M_6FB2
        RLC
        JC L_0D6F
        MOV A,L
        SUI 40H                     ; '@'
        LHLD M_6FB3
        LXI D,CUR_FLAGS
        LDAX D
        JM L_0D44
        ORI 20H                     ; ' '
        LXI H,RESET
        JMP L_0D47
L_0D44:
        ANI 0DFH
        INX H
L_0D47:
        STAX D
        SHLD M_6FB3
        LXI H,M_6FB1
        INR M
        MOV A,M
        CPI 05H
        POP B
        RNZ
        MVI M,00H
        LDAX B
        MOV L,A
        MVI H,00H
        MOV E,A
        RLC
        JNC L_0D6A
        MVI H,0FFH
        PUSH D
        LXI D,D_005C
        DAD D
        POP D
        MOV A,H
        RLC
        RC
L_0D6A:
        MOV A,E
        SUI 03H
        STAX B
        RET
L_0D6F:
        LHLD M_6FB3
        LXI D,CUR_FLAGS
        LDAX D
        JMP L_0D44
X_0D79:
        CALL X_0DB3
        JMP REC_TO_FRONTEND
SUB_0D7F:
        LDA SLOT_IDX
        CPI 00H
        JNZ L_0D93
        LDA M_6FA8
        CALL BCD_TO_BIN
        STA VAR_6FE2
        JMP SUB_0DB0
L_0D93:
        LDA VAR_6FE2
        RRC
        RRC
        JNC SUB_0DB0
        LXI H,VAR_6FE3
        LXI B,CUR_TOA
        CALL BCD_ADD4
        CALL SUB_0DB0
        LXI H,VAR_6FE3
        LXI B,CUR_TOA
        JMP BCD_SUB4
SUB_0DB0:
        LDA CUR_REC
X_0DB3:
        LXI H,CUR_TOA
        PUSH PSW
        LXI B,CUR_REC
        CALL COPY4
        DCX B
        LDAX B
        ANI 0FEH
        CALL BCD_TO_BIN
        RRC
        CALL BIN_TO_BCD
        RLC
        MOV D,A
        PUSH D
        LXI H,CUR_REC
        LXI D,D_0003
L_0DD1:
        MOV A,M
        RAR
        MOV M,A
        INX H
        DCR E
        JNZ L_0DD1
        POP D
        MOV A,D
        RAR
        MOV M,A
        POP PSW
        LXI B,CUR_REC
        STAX B
        RET
CUR_REC_TO_FRONTEND:
        LXI B,CUR_REC

; REC_TO_FRONTEND: BC = pointer to a 4-byte-BCD-fronted record (REC_MASTER or CUR_REC
; in practice - never a fixed operand, always whatever the caller left in BC).
; Byte 0 (the record's status byte, e.g. CUR_REC's "bit0=skip in ISR") has bits
; 2,4,5,6 of the CURRENT PIO2_PB merged in and bits 0,1,3 written out to PIO2_PB
; (correcting hardware.md's old "static, meaning unknown" for those bits).
; Bytes 1-3 (the record's actual BCD digits) are written raw, one each, to
; PIO1_PB (E002), PIO1_PA (E001), PIO2_PA (F001) - ports previously documented as
; "never touched" before this ROM half was recovered. Then PIO2_PB bit 7 is set.
; Called only at station-selection transitions - SEARCH_LOOP start (BC=REC_MASTER),
; after SLOT_ACQUIRE's secondary search starts (BC=REC_MASTER), and SETTLE_LOOP
; start via CUR_REC_TO_FRONTEND (BC=CUR_REC) - never every epoch inside a loop.
; Hypothesis (not certain): this broadcasts the newly-selected station's current
; BCD value to the analog front end in parallel, as a feed-forward timing hint for
; the "pulse-group timing" hardware.md already infers lives on that board -
; consistent with the board's silkscreened SAMPLER/TRF sections. Needs the
; physical board to confirm.
REC_TO_FRONTEND:
        LDA PIO2_PB
        ANI 74H                     ; 't'
        MOV L,A
        LDAX B
        ANI 0BH
        ORA L
        STA PIO2_PB
L_0DF3:
        INX B
        LDAX B
        STA M_E002
        INX B
        LDAX B
        STA M_E001
        INX B
        LDAX B
        STA M_F001
        LDA PIO2_PB
        ORI 80H
        STA PIO2_PB
        RET
L_0E0B:
        LDA PIO2_PB
        ANI 7FH
        STA PIO2_PB
        LDAX B
        STA M_6FDB
        JMP L_0DF3
X_0E1A:
        CALL X_0E2D
X_0E1D:
        LDA PIO2_PB
        ANI 0F4H
        MOV L,A
        LDA M_6FDB
        ANI 0BH
        ORA L
        STA PIO2_PB
        RET
X_0E2D:
        LXI H,SLOT_COUNT
        LDA SLOT_IDX
L_0E33:
        INR A
        CMP M
        JZ L_0E58
        PUSH H
        PUSH PSW
        CALL GET_FLAGS_A
        MOV B,A
        RLC
        JNC L_0E53
        RLC
        JC L_0E5F
        LDA TRACK_STATE
        CPI 80H
        JZ L_0E5F
        CPI 40H                     ; '@'
        JZ L_0E5F
L_0E53:
        POP PSW
        POP H
        JMP L_0E33
L_0E58:
        XRA A
        LXI H,REC_MASTER
        JMP L_0E65
L_0E5F:
        MOV A,B
        CALL GET_SEC_REC
        POP PSW
        POP D
L_0E65:
        MOV B,H
        MOV C,L
        JMP L_0E0B
PULSE_ALIGN_ADJ_6FBE:
        LDA PULSE_ALIGN_FLAGS

; PULSE_ALIGN_ADJ: A = flags byte (normally PULSE_ALIGN_FLAGS, was M_6FBE). Tests bits
; 7,6,5,4 in that order (successive RLC), independently CALLing (any/all can fire):
; bit7 -> TOA_SUB_1000, bit6 -> TOA_ADD_1000, bit5 -> TOA_ADD_6000, bit4 -> TOA_SUB_2000.
; Corrects CUR_TOA by whole multiples of the ~1000us Loran-C inter-pulse spacing - the fix
; for the phase-code correlator locking onto the wrong pulse within the 8-pulse group.
; PULSE_ALIGN_ADJ_6FBE (0E6A) is the same cascade pre-loaded with A = PULSE_ALIGN_FLAGS.
; PULSE_ALIGN_ADJ2 (0E87) is a shorter 2-bit variant (bit7/bit6 only, i.e. just the
; +-1000 pair).
PULSE_ALIGN_ADJ:
        RLC
        PUSH PSW
        CC TOA_SUB_1000
        POP PSW
        RLC
        PUSH PSW
        CC TOA_ADD_1000
        POP PSW
        RLC
        PUSH PSW
        CC TOA_ADD_6000
        POP PSW
        RLC
        PUSH PSW
        CC TOA_SUB_2000
        POP PSW
        RLC
        RET
PULSE_ALIGN_ADJ2:
        RLC
        PUSH PSW
        CC TOA_SUB_1000
        POP PSW
        RLC
        CC TOA_ADD_1000
        RET
PULSE_ALIGN_ADJ2_AND_CLEAR:
        CALL PULSE_ALIGN_ADJ2

; CLEAR_TRACK_VARS: zero PHASE_QUAL_A, PHASE_QUAL_B (via SHLD of the RESET vector's
; 0000H, a code-golf reuse of an existing zero word rather than a fresh 00,00 immediate)
; and M_6FB2. PULSE_ALIGN_ADJ2_AND_CLEAR (0E92) is CALL PULSE_ALIGN_ADJ2 falling straight
; through into this same body (no RET in between) - the two are almost always used
; as one combined operation; this entry point alone is only reached directly from 08EB.
CLEAR_TRACK_VARS:
        LXI H,RESET
        SHLD PHASE_QUAL_A
        SHLD PHASE_QUAL_B
        MOV A,H
        STA M_6FB2
        RET
TOA_SUB_1000:
        LXI H,TOA_ADJ_1000

; TOA_SUB_CONST: HL = pointer to a 4-byte BCD constant. CUR_TOA -= (HL). The subtract
; sibling of TOA_ADD_CONST (0EC1); TOA_SUB_1000/_2000/_3000/_6000 are fixed-constant
; entry points into this same tail (see PULSE_ALIGN_ADJ, 0E6D).
TOA_SUB_CONST:
        LXI B,CUR_TOA
        JMP BCD_SUB4
TOA_SUB_2000:
        LXI H,TOA_ADJ_2000
        JMP TOA_SUB_CONST
TOA_SUB_3000:
        LXI H,TOA_ADJ_3000
        JMP TOA_SUB_CONST
TOA_SUB_6000:
        LXI H,TOA_ADJ_6000
        JMP TOA_SUB_CONST
TOA_ADD_1000:
        LXI H,TOA_ADJ_1000

; TOA_ADD_CONST (was X_0EC1; the old rom-status.md guess "add BCD constant to CUR_TOA"
; was exactly right). HL = pointer to a 4-byte BCD constant. CUR_TOA += (HL).
; TOA_ADD_1000/_3000/_6000 are fixed-constant entry points into this same tail (see
; PULSE_ALIGN_ADJ, 0E6D); the other 4 callers pass BCD_K_00080980 or BCD_K_00000110
; (0004's table) or another caller-chosen constant, not yet individually traced.
TOA_ADD_CONST:
        LXI B,CUR_TOA
        JMP BCD_ADD4
L_0EC7:
        LXI H,TOA_ADJ_2000
        JMP TOA_ADD_CONST
TOA_ADD_3000:
        LXI H,TOA_ADJ_3000
        JMP TOA_ADD_CONST
TOA_ADD_6000:
        LXI H,TOA_ADJ_6000
        JMP TOA_ADD_CONST
X_0ED9:
        LXI H,DISP_MODE
        INR M
        MOV A,M
        CPI 0AH
        JC L_0EE5
        MVI M,00H
L_0EE5:
        LXI H,RESTART_REQ
        MOV A,M
        CPI 00H
        RZ
        DCR M
        RET
X_0EEE:
        LXI H,NEW_DATA
        MOV A,M
        MVI M,00H
        RRC
        RNC
        LXI H,TRACK_STATE
        MVI M,01H
        DCX H
        MOV A,M
        CALL GET_FLAGS_A
        ANI 0C0H
        CPI 80H
        RNZ
        MVI M,00H
        RET
X_0F08:
        LDA TRACK_STATE
        CPI 01H
        RNZ
        LDA ACQ_COUNT
        CPI 04H
        RP
        LDA SLOT_RESULT
        CPI 00H
        RZ
        MOV D,A
        PUSH D
        CALL GET_FLAGS_A
        POP D
        RLC
        RC
        MOV A,D
X_0F23:
        STA SLOT_IDX_B
        CALL GET_FLAGS_A
        MVI M,80H
        MVI A,20H                   ; ' '
        STA TRACK_STATE
        RET
X_0F31:
        LDA SLOT_FLAGS
        MOV B,A
        LXI H,RAM1_BASE
        MOV A,M
        CPI 00H
        PUSH H
        JNZ L_0F5C
        LDA FIRST_SLOT
        CALL GET_FLAGS_A
        ANI 60H                     ; '`'
        CPI 60H                     ; '`'
        XCHG
        POP H
        RNZ
        MVI M,01H
        LXI H,REC_MASTER
        CALL X_0FE9
L_0F54:
        LDA FIRST_SLOT
        MOV B,A
        XRA A
        JMP L_0F6F
L_0F5C:
        CPI 01H
        POP H
        JNZ L_0F9E
        MOV A,B
        ANI 10H
        JZ L_0FBC
        MVI M,02H
X_0F6A:
        MVI B,00H
        LDA FIRST_SLOT
L_0F6F:
        PUSH B
        PUSH PSW
        CALL GET_FLAGS_A
        MOV A,M
        ANI 0F7H
        MOV M,A
        POP PSW
        CPI 00H
        LXI H,M_6F2D
        LXI D,M_6F46
        JZ L_0F85
        XCHG
L_0F85:
        POP B
        PUSH D
        PUSH H
        MOV A,B
        CALL GET_FLAGS_A
        MOV A,M
        ORI 08H
        MOV M,A
        POP H
        POP B
        PUSH H
        MVI E,05H
        CALL COPY_E
        POP H
        MVI B,05H
        JMP FILL_ZERO
L_0F9E:
        MOV A,B
        LHLD M_6F36
        LXI D,M_FF9C
        DAD D
        ANI 08H
        JZ CHK_H_NEG
        MOV A,H
        RLC
        JC L_0FBC
        LDA FIRST_SLOT
        CALL GET_FLAGS_A
        RLC
        RLC
        JC L_0F54
        RET
L_0FBC:
        MVI A,01H
X_0FBE:
        PUSH PSW
        CALL GET_FLAGS_A
        MOV B,A
        RLC
        RLC
        JNC L_1018
        RLC
        RLC
        JC L_1018
        MOV A,B
        CALL GET_SEC_REC
        MOV A,M
        ANI 80H
        JNZ L_1018
        POP PSW
        MOV B,A
        LDA FIRST_SLOT
        CMP B
        JNZ L_0FF7
        LDA RAM1_BASE
        CPI 02H
        MOV A,B
        JNZ SLOT_INC_CHK
X_0FE9:
        MOV A,M
        ORI 82H
        MOV M,A
        LXI D,BCD_K_00000110
        DAD D
        MVI M,00H
        DCX H
        MVI M,00H
        RET
L_0FF7:
        PUSH PSW
        PUSH H
        PUSH B
        MOV A,B
        RLC
        MOV C,A
        RLC
        RLC
        ADD C

; SLOTTBL_CHK: tail of a routine spanning the ROM 1/ROM 2 boundary (entered from 0FFxH):
; test SLOT_TBL[A]; clean up stack and continue at X_0FE9 or SLOT_INC_CHK.
SLOTTBL_CHK:
        MOV C,A
        MVI B,00H
D_1004       EQU  $+1
        LXI H,SLOT_TBL
        DAD B
        MOV A,M
        CPI 00H
        POP B
        POP H
        JZ SLOTTBL_ZERO
        POP PSW
        JMP X_0FE9
SLOTTBL_ZERO:
        POP PSW
        MOV A,B
        JMP SLOT_INC_CHK
L_1018:
        POP PSW
SLOT_INC_CHK:
        INR A
        LXI H,SLOT_COUNT
        CMP M
        JNZ X_0FBE
        RET
CHK_H_NEG:
        MOV A,H
        RLC
        JC X_0F6A
        RET

; SLOTREC_PHASE: update the 9-byte per-slot record from PHASE_CODE_HI.
SLOTREC_PHASE:
        LDA SLOT_IDX
        LXI H,SLOTREC_5
        CALL MUL9_INDEX
        MOV C,M
        LDA PHASE_CODE_HI
        XRI 3FH                     ; '?'
        DCR C
        DCR C
        DCR C
        MVI E,03H
SRP_LOOP:
        RLC
        JNC SRP_NEXT
        INR C
        INR C
SRP_NEXT:
        DCR E
        JNZ SRP_LOOP
        MOV A,C
        ADI 08H
        RLC
        MVI A,00H
        RAR
        INX H
        MOV M,A
        DCX H
        MOV A,C
        RLC
        JNC SRP_STORE
        MOV A,C
        ADI 10H
        RLC
        RNC
SRP_STORE:
        MOV M,C
        RET

; SLOTREC_UPDATE: bump the per-slot counter, subtract BCD_TMP / 0400H, add popcount, etc.
SLOTREC_UPDATE:
        LDA SLOT_IDX
        LXI H,SLOTREC_CNT
        CALL MUL9_INDEX
        INX H
        PUSH H
        DCX H
        INR M
        MOV A,M
        CPI 02H
        JZ SRU_SUB
        CPI 05H
        JNZ SRU_SUB4
        MVI M,00H
SRU_SUB:
        POP H
        PUSH H
        LXI B,M_6FEA
        CALL COPY4
        LXI H,BCD_TMP
        MVI M,00H
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_SUB4
SRU_SUB4:
        LXI B,0400H                 ; B = 4 bytes (C ignored)
        LXI H,BCD_TMP
        CALL FILL_ZERO
        LXI H,BCD_TMP_2
        MVI M,04H
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_SUB4
        LXI H,BCD_TMP_2
        MVI M,00H
        LDA PHASE_CODE_HI
        CMA
        MVI E,08H
SRU_CNT_LOOP:
        RRC
        JNC SRU_CNT_NEXT
        INR M
SRU_CNT_NEXT:
        DCR E
        JNZ SRU_CNT_LOOP
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_ADD4
        POP B
        LDAX B
        CPI 00H
        JZ SRU_ZERO
        MOV H,B
        MOV L,C
        PUSH B
        MVI B,04H
        CALL FILL_ZERO
        POP B
        RET
SRU_ZERO:
        INX B
        LDAX B
        ANI 0F0H
        RZ
        MVI A,10H
        STAX B
        INX B
        MVI A,00H
        STAX B
        RET

; CALL_TICK_HOOK: jump through TICK_HOOK. Nothing in the fully-recovered ROM ever writes
; TICK_HOOK, so in practice it's only ever set (if at all) by the serial monitor's
; memory-write command - this is a runtime debug hook, not used by the firmware itself.
CALL_TICK_HOOK:
        LHLD TICK_HOOK
        PCHL

; SERIAL_POLL: 8251 receive state machine (RX_STATE / PROTO_STATE). See docs/serial-protocol.md.
; Also runs PLOT_OUT when OUT_MODE = 2.
SERIAL_POLL:
        LDA OUT_MODE
        CPI 02H
        CZ PLOT_OUT
        LDA RX_STATE
        CPI 00H
        JNZ RX_STATE_N
        LDA USART_CTRL
        RAR                         ; RxRDY?
        RAR
        RNC
        LDA USART_DATA
        STA RX_CHAR
        LDA RX_STATE
        INR A
        STA RX_STATE
        JMP SERIAL_POLL
RX_STATE_N:
        LDA USART_CTRL
        RAR                         ; TxRDY?
        RNC
        LDA PIO1_PC
        ORI 01H
        STA PIO1_PC
        LDA RX_STATE
        INR A
        STA RX_STATE
        CPI 02H
        JNZ TX_STATE_N
        LDA RX_CHAR
        CPI 12H                     ; DC2: reset protocol
        JNZ RX_CMD_14
        MVI A,00H
        STA PROTO_STATE
        STA OUT_MODE
        JMP RX_DONE
RX_CMD_14:
        CPI 14H                     ; DC4: OUT_MODE = 1
        JNZ RX_CMD_07
        MVI A,01H
        STA OUT_MODE
        JMP RX_DONE
RX_CMD_07:
        CPI 07H                     ; BEL: reset print buffer, PROTO_STATE = 1
        JNZ RX_CMD_05
        LXI H,PRTBUF
        SHLD PRTBUF_PTR
        MVI A,00H
        STA OUT_MODE
        MVI A,01H
        STA PROTO_STATE
        JMP RX_DONE
RX_CMD_05:
        CPI 05H                     ; ENQ: PROTO_STATE = 2
        JNZ RX_PROTO_4
        MVI A,02H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_4:
        LDA PROTO_STATE
        CPI 04H
        JNZ RX_PROTO_5
        LDA RX_CHAR
        CPI 41H                     ; 'A'
        JNZ RX_PROTO_4B
        MVI A,05H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_4B:
        CPI 2CH                     ; ','
        JNZ RX_PROTO_RESET
        MVI A,06H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_RESET:
        MVI A,00H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_5:
        LDA PROTO_STATE
        CPI 05H
        JNZ RX_PROTO_6
        LDA RX_CHAR
        LXI H,UNIT_ID
        CMP M
        JNZ RX_PROTO_SET1
        MVI A,02H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_SET1:
        MVI A,01H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_6:
        LDA PROTO_STATE
        CPI 06H
        JNZ RX_CHK_ESC
        LDA RX_CHAR
        LXI H,UNIT_ID
        CMP M
        JNZ RX_PROTO_SET1
        MVI A,03H
        STA PROTO_STATE
        JMP RX_DONE
RX_CHK_ESC:
        LDA RX_CHAR
        CPI 1BH                     ; ESC: PROTO_STATE = 4
        JNZ RX_CHK_MON
        MVI A,04H
        STA PROTO_STATE
        JMP RX_DONE
RX_CHK_MON:
        LDA PROTO_STATE
        CPI 03H
        JZ MON_CMD
RX_DONE:
        MVI A,00H
        STA RX_STATE
        RET

; MON_CMD: memory monitor commands, active when PROTO_STATE = 3. Char is echoed first.
;   ' ' deposit MON_WORD low byte at (MON_PTR), advance   R back up one address
;   S set MON_PTR = MON_WORD   G call MON_WORD   M dump memory   K/P/O output mode 1/2/0
;   0-9 A-F shift hex digit into MON_WORD
MON_CMD:
        LDA RX_CHAR
        STA USART_DATA              ; echo command char
        CPI 20H                     ; ' '
        JNZ MON_CMD_R
        LDA MON_DIGIT_FLAG
        CPI 00H
        LHLD MON_PTR
        JZ MON_ADVANCE
        LDA MON_WORD
        MOV M,A
MON_ADVANCE:
        INX H
        SHLD MON_PTR
MON_CLR_DIGIT:
        MVI A,00H
        STA MON_DIGIT_FLAG
        JMP SERIAL_POLL
MON_CMD_R:
        CPI 52H                     ; 'R'
        JNZ MON_CMD_S
        LHLD MON_PTR
        DCX H
        SHLD MON_PTR
        JMP MON_CLR_DIGIT
MON_CMD_S:
        CPI 53H                     ; 'S'
        JNZ MON_CMD_G
        LHLD MON_WORD
        SHLD MON_PTR
        JMP MON_CLR_DIGIT
MON_CMD_G:
        CPI 47H                     ; 'G'
        JNZ MON_CMD_K
        CALL MON_GO
        JMP MON_CLR_DIGIT
MON_GO:
        LHLD MON_WORD
        PCHL
MON_CMD_K:
        CPI 4BH                     ; 'K'
        JNZ MON_CMD_P
        MVI A,01H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_CMD_P:
        CPI 50H                     ; 'P'
        JNZ MON_CMD_M
        MVI A,02H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_CMD_M:
        CPI 4DH                     ; 'M'
        JNZ MON_CMD_O
        MVI A,0CH
        STA RX_STATE
        JMP SERIAL_POLL
MON_CMD_O:
        CPI 4FH                     ; 'O'
        JNZ MON_HEX_DIGIT
        MVI A,00H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_HEX_DIGIT:
        CPI 3AH                     ; ':'
        JM MON_HEX_SHIFT
        ADI 09H
MON_HEX_SHIFT:
        ANI 0FH
        LHLD MON_WORD
        DAD H
        DAD H
        DAD H
        DAD H
        ORA L
        MOV L,A
        SHLD MON_WORD
        MVI A,00H
        STA RX_STATE
        MVI A,01H
        STA MON_DIGIT_FLAG
        JMP SERIAL_POLL
TX_STATE_N:
        CPI 03H
        JZ TX_CR                    ; state 3: send CR
        CPI 04H
        JZ TX_LF                    ; state 4: send LF
        CPI 05H
        JZ TX_PTR_HI
        CPI 06H
        JZ TX_ECHO                  ; state 6/8/B: echo char
        CPI 07H
        JZ TX_PTR_LO
        CPI 08H
        JZ TX_ECHO
        CPI 09H
        JZ TX_SPACE                 ; state 9: send space
        CPI 0AH
        JZ TX_MEM_BYTE
        CPI 0BH
        JZ TX_ECHO
        CPI 0CH
        JNZ TX_WAIT_TXRDY
        XRA A
        STA MON_WORD
        STA MON_WORD_HI
        STA RX_STATE

; TX_DASH: send '-'. The three LXI H instructions are 21H skip-prefixes over
; MVI A,' ' / MVI A,0DH / MVI A,0AH so that entries at 12D1/12D4/12D7 send those chars.
TX_DASH:
        MVI A,2DH                   ; '-'
TX_SPACE     EQU  $+1
        LXI H,203EH                 ; 21H skip prefix: MVI A,' ' at 12D1
TX_CR        EQU  $+1
        LXI H,0D3EH                 ; 21H skip prefix: MVI A,0DH at 12D4
TX_LF        EQU  $+1
        LXI H,0A3EH                 ; 21H skip prefix: MVI A,0AH at 12D7
        STA USART_DATA
        JMP SERIAL_POLL
TX_WAIT_TXRDY:
        LDA USART_CTRL
        RAR
        RAR
        JNC TX_DUMP_STATE
        XRA A
        STA RX_STATE
        JMP SERIAL_POLL
TX_DUMP_STATE:
        LDA RX_STATE
        CPI 0DH
        JZ TX_DUMP_BYTE
        CPI 0EH
        JZ TX_ECHO
        MVI A,0CH
        STA RX_STATE
        JMP TX_DASH
TX_DUMP_BYTE:
        LHLD MON_WORD
        LDA MON_LAST
        CMP M
        JZ TX_DUMP_SAME
        MOV A,M
        STA MON_LAST
        JMP TX_HEX_BYTE
TX_DUMP_SAME:
        MVI A,0CH
        STA RX_STATE
        RET
TX_ECHO:
        LDA RX_CHAR
        STA USART_DATA
        JMP SERIAL_POLL
TX_PTR_LO:
        LDA MON_PTR
        JMP TX_HEX_BYTE
TX_PTR_HI:
        LDA MON_PTR_HI
TX_HEX_BYTE:
        PUSH PSW
        RAR
        RAR
        RAR
        RAR
        ANI 0FH
        CPI 0AH
        JM TX_HEX_HI
        ADI 07H
TX_HEX_HI:
        ADI 30H                     ; '0'
        STA USART_DATA
        POP PSW
        ANI 0FH
        CPI 0AH
        JM TX_HEX_LO
        ADI 07H
TX_HEX_LO:
        ADI 30H                     ; '0'
        STA RX_CHAR
        JMP SERIAL_POLL
TX_MEM_BYTE:
        LHLD MON_PTR
        MOV A,M
        JMP TX_HEX_BYTE

; PLOT_OUT: strip-chart output mode. Emits CR, LF then 80 columns with ' ' / '!' / '"' / '#'
; marking the two values from PLOT_VALUES.
PLOT_OUT:
        LDA USART_CTRL
        RRC
        RNC
        LDA PIO1_PC
        ORA C
        STA PIO1_PC
        LDA PLOT_COL
        CPI 50H                     ; 'P'
        MVI D,0DH
        JZ PLOT_SEND
        LDA PLOT_COL
        CPI 51H                     ; 'Q'
        JNZ PLOT_COLUMN
        MVI A,00H
        STA PLOT_COL
        CALL PLOT_VALUES
        MOV H,B
        MOV L,C
        SHLD PLOT_BASE
        MVI D,0AH
        JMP PLOT_SEND
PLOT_COLUMN:
        LHLD PLOT_BASE
        MOV B,H
        MOV C,L
        MVI D,20H                   ; ' '
        LDA PLOT_COL
        CMP B
        JNZ PLOT_CHK_C
        MOV A,D
        ORI 01H
        MOV D,A
PLOT_CHK_C:
        CMP C
        JNZ PLOT_SEND
        MOV A,D
        ORI 02H
        MOV D,A
PLOT_SEND:
        LXI H,PLOT_COL
        INR M
        MOV A,D
        STA USART_DATA
        RET
PLOT_VALUES:
        LDA SEL_A
        LXI H,REC_MASTER_14
        CPI 0AH
        JNC PV_SCALE
        LXI H,SLOT_FLAGS
        ADD L
        MOV L,A
        MOV A,M
        LXI H,REC_SEC_14
PV_INDEX:
        ANI 03H
        LXI D,0019H                 ; record stride 25
        DCR A
        JM PV_SCALE
        DAD D
        JMP PV_INDEX
PV_SCALE:
        MOV A,M
        RRC
        RRC
        ADI 08H
        ANI 3FH                     ; '?'
        INR A
        INR A
        INR A
        MOV B,A
        INX H
        INX H
        INX H
        MOV A,M
        CMA
        RRC
        RRC
        ADI 08H
        ANI 3FH                     ; '?'
        INR A
        INR A
        INR A
        MOV C,A
        RET

; DISP_REFRESH: write the 8279 display RAM (cmd 90H = write, auto-inc, addr 0).
; 7 bytes: 3 pairs interleaving high nibbles of 7034..7036 with 7037..7039, then 703A.
; Reached by a plain JMP from L_1CEA, the shared display-commit tail used by
; SW_ERR_SHOW and friends.
DISP_REFRESH:
        MVI A,90H
        STA KDC_CMD
        LXI B,DISP_ROW_B
        LXI H,DISP_ROW_A
        MVI E,03H
DISP_LOOP:
        MOV A,M
        ANI 0F0H
        MOV D,A
        LDAX B
        RRC
        RRC
        RRC
        RRC
        ANI 0FH
        ORA D
        STA KDC_DATA
        MOV A,M
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV D,A
        LDAX B
        ANI 0FH
        ORA D
        STA KDC_DATA
        INX H
        INX B
        DCR E
        JNZ DISP_LOOP
        LDA DISP_EXTRA
        STA KDC_DATA
        RET

; READ_SWITCHES: read the 6 thumbwheel rows via the 8279 sensor RAM (cmd 50H).
; Rows 0,1 -> SEL_A/SEL_B (digit+1, must be 1..9); rows 2..5 -> GRI (first digit >= 4).
; Invalid settings call SW_ERR_SEL_A/SW_ERR_SEL_B/SW_ERR_GRI1..4 and retry.
READ_SWITCHES:
        MVI A,0E0H
        STA KDC_CMD                 ; 8279: end interrupt
        MVI A,50H                   ; 'P'
        STA KDC_CMD                 ; 8279: read sensor RAM row 0, auto-inc
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        CPI 0AH
        JC RSW_SELB
        CALL SW_ERR_SEL_A
        JMP READ_SWITCHES
RSW_SELB:
        STA SEL_A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        CPI 0AH
        JC RSW_GRI1
        CALL SW_ERR_SEL_B
        JMP READ_SWITCHES
RSW_GRI1:
        STA SEL_B
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI1_CHK
        CALL SW_ERR_GRI1
        JMP READ_SWITCHES
RSW_GRI1_CHK:
        CPI 04H
        JNC RSW_GRI2                ; GRI first digit must be 4..9
        CALL SW_ERR_GRI1
        JMP READ_SWITCHES
RSW_GRI2:
        RLC
        RLC
        RLC
        RLC
        MOV L,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI3
        CALL SW_ERR_GRI2
        JMP READ_SWITCHES
RSW_GRI3:
        ORA L
        MOV L,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI4
        CALL SW_ERR_GRI3
        JMP READ_SWITCHES
RSW_GRI4:
        RLC
        RLC
        RLC
        RLC
        MOV H,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_STORE_GRI
        CPI 0BH
        JZ RSW_GRI4_BLANK
        CALL SW_ERR_GRI4
        JMP READ_SWITCHES
RSW_GRI4_BLANK:
        MVI A,00H
RSW_STORE_GRI:
        ORA H
        MOV H,A
        SHLD GRI_SW
        JMP SCAN_SWITCHES

; SW_TO_DIGIT: convert a sensor row byte to a digit. Rows are 9's-complement BCD on bits 0..5:
; digit = 9 - (row & 3FH), valid (carry set) when row & 3FH <= 9. Otherwise returns
; 0BH for the blank position (carry clear).
SW_TO_DIGIT:
        ANI 3FH                     ; '?'
        XRI 0FFH
        ADI 0AH
        CPI 0AH
        RC
        RRC
        RRC
        RRC
        RRC
        ADI 0CH
        ANI 0FH
        STC
        CMC
        RET

; TICK_TASK: run once per RST 7.5 tick. TICK_BCD += 2 (BCD); every 20 ticks call X_19E7.
; If RST 5.5 (8279 IRQ) is pending: send End-Interrupt (0E0H) and set KEY_CHANGED;
; on a later tick with KEY_CHANGED set, rescan the switches.
TICK_TASK:
        LDA TICK_BCD
        INR A
        INR A
        XRI 00H
        DAA
        STA TICK_BCD
        ANI 3FH                     ; '?'
        CZ X_19E7
        RIM
        ANI 10H
        JZ TICK_CHK_KEYS
        MVI A,0E0H
        STA KDC_CMD                 ; 8279: end interrupt (clear IRQ)
        MVI A,01H
        STA KEY_CHANGED
        RET
TICK_CHK_KEYS:
        LDA KEY_CHANGED
        CPI 00H
        RZ

; SCAN_SWITCHES: read sensor rows 0..5 and 6..7. Row 0/1 -> SEL_A/SEL_B, rows 2..5 -> SW_D1..4,
; rows 6/7 bit 7/6 -> BTN_STATE / BUTTONS (push-button edges).
; SEL_B = 0CH (blank) enters set-up: SW_D1..4 latched to SW_HI/SW_LO; SW_D1 = blank selects
; a configuration item by SW_D2: 0-3 baud (110/300/1200/19200), 4-9 OPTIONS bits.
SCAN_SWITCHES:
        MVI A,50H                   ; 'P'
        STA KDC_CMD                 ; 8279: read sensor RAM row 0, auto-inc
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        STA SEL_A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        STA SEL_B
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D1
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D2
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D3
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D4
        MVI A,00H
        STA KEY_CHANGED
        MVI A,56H                   ; 'V'
        STA KDC_CMD                 ; 8279: read sensor RAM row 6, auto-inc
        LDA KDC_DATA
        MOV B,A
        ANI 80H
        JZ SCAN_BTN_ROW7
        LDA BTN_STATE
        XRI 80H
        STA BTN_STATE
SCAN_BTN_ROW7:
        MOV A,B
        ANI 40H                     ; '@'
        RLC
        MOV B,A
        LDA KDC_DATA
        MOV C,A
        ANI 80H
        JZ SCAN_BTN_CLR
        LDA BTN_STATE
        ORI 40H                     ; '@'
        JMP SCAN_BTN_STORE
SCAN_BTN_CLR:
        LDA BTN_STATE
        ANI 0BFH
SCAN_BTN_STORE:
        STA BTN_STATE
        MOV A,C
        ANI 40H                     ; '@'
        ORA B
        STA BUTTONS
        LDA SEL_B
        CPI 0CH                     ; SEL_B blank -> set-up mode
        JNZ SCAN_NORMAL
        LDA BTN_STATE
        MOV B,A
        ANI 40H                     ; '@'
        STA BTN_STATE
        MOV A,B
        RLC
        JNC SCAN_BTN_EDGES
        LDA SW_LATCHED
        CPI 00H
        JNZ SCAN_CLR_STATS
        LDA SW_D1
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D2
        ANI 0FH
        ORA B
        STA SW_HI
        LDA SW_D3
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D4
        ANI 0FH
        ORA B
        STA SW_LO
        MVI A,00H
        STA VAR_704F
        MVI A,01H
        STA SW_LATCHED
        JMP SCAN_BTN_EDGES
SCAN_CLR_STATS:
        MVI A,00H
        STA VAR_70BD
        STA VAR_70BE
        STA VAR_7050
        STA VAR_7051
SCAN_BTN_EDGES:
        LDA BUTTONS
        MOV B,A
        MVI A,00H
        STA BUTTONS
        MOV A,B
        RLC
        JNC SCAN_BTN_EDGE2
        LDA STATUS_BITS
        ORI 80H
        STA STATUS_BITS
SCAN_BTN_EDGE2:
        MOV A,B
        RLC
        RLC
        JNC SCAN_DONE
        LDA STATUS_BITS
        ANI 7FH
        STA STATUS_BITS
SCAN_DONE:
        RET
SCAN_NORMAL:
        LDA BUTTONS
        CPI 00H
        RZ
        LDA SEL_B
        CPI 0BH
        RZ
        MVI A,02H
        STA RESTART_REQ
        LDA BUTTONS
        ANI 40H                     ; '@'
        RZ
        LDA SW_D1
        CPI 0BH                     ; SW_D1 blank -> configuration item
        JNZ SCAN_SEL_CHK
        LDA SW_D3
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D4
        ORA B
        STA UNIT_ID
        LDA SW_D2
        CPI 00H
        JNZ CFG_BAUD_1
        LXI H,458AH                 ; timer 058AH (1418): 110 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_1:
        CPI 01H
        JNZ CFG_BAUD_2
        LXI H,4208H                 ; timer 0208H (520): 300 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_2:
        CPI 02H
        JNZ CFG_BAUD_3
        LXI H,4082H                 ; timer 0082H (130): 1200 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_3:
        CPI 03H
        JNZ CFG_OPT_4
        LXI H,4008H                 ; timer 0008H (8): 19200 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_OPT_4:
        CPI 04H
        JNZ CFG_OPT_5
        MVI A,00H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_5:
        CPI 05H
        JNZ CFG_OPT_6
        MVI A,81H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_6:
        CPI 06H
        JNZ CFG_OPT_7
        MVI A,82H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_7:
        CPI 07H
        JNZ CFG_OPT_8
        MVI A,84H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_8:
        CPI 08H
        JNZ CFG_OPT_9
        MVI A,88H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_9:
        CPI 09H
        JNZ SCAN_SEL_CHK
        MVI A,80H
        STA OPTIONS
SCAN_SEL_CHK:
        LDA SEL_A
        LXI H,SLOT_COUNT
        CMP M
        RP
        CALL X_1DBD
        JC SCAN_SEL_STORE
        LDA SLOT_IDX_B
        CALL GET_FLAGS_A
        ANI 0C0H
        CPI 80H
        RZ
        CALL X_1E05
SCAN_SEL_STORE:
        STA SLOT_RESULT
        MVI A,01H
        STA NEW_DATA
        RET

; TX_SERVICE: when OUT_MODE = 0 and 8251 TxRDY, send next char from PRTBUF.
TX_SERVICE:
        LDA OUT_MODE
        CPI 00H
        RNZ
        LDA USART_CTRL
        RRC
        RNC
        LDA TX_PENDING
        RRC
        RC
        LDA PIO1_PC
        ORI 01H
        STA PIO1_PC
        CALL PRTBUF_GET
        JNC TX_SEND
        MVI A,01H
        STA TX_PENDING
        RET
TX_SEND:
        STA USART_DATA
        RET

; PRTBUF_GET: pull next char from the print buffer (PRTBUF_PTR walks down to PRTBUF).
PRTBUF_GET:
        LHLD PRTBUF_PTR
        LXI D,PRTBUF
        MOV A,D
        CMP H
        JNZ PRTBUF_POP
        MOV A,E
        CMP L
        JNZ PRTBUF_POP
        MOV A,M
        STC
        RET
PRTBUF_POP:
        STC
        CMC
        DCX H
        MOV A,M
        SHLD PRTBUF_PTR
        RET

; REPORT_TASK: sequence the periodic data report over the serial port (RPT_STATE 0..8,
; 0FEH = idle, 0FFH = armed). Items are formatted by PRT_HEX_HI_SP / PRT_HEX_BYTE and,
; for item 0 (GRI) or the 7056H-indexed items, by RPT_FMT_TD3; see 186D for the whole
; print-buffer formatting cluster (186D-19E7).
REPORT_TASK:
        LDA RPT_STATE
        CPI 0FEH
        JNZ RPT_RUNNING
        LDA PROTO_STATE
        CPI 00H
        JZ RPT_CHK_IDLE
        CPI 02H
        RNZ
        MVI A,01H
        STA PROTO_STATE
        JMP RPT_ARM
RPT_CHK_IDLE:
        LDA TICK_BCD
        CPI 00H
        RNZ
        LDA OPTIONS
        RLC
        JNC RPT_ARM
        LDA VAR_704F
        ANI 0FH
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        JC RPT_ARM
        LDA VAR_704F
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        JC RPT_ARM
        LDA SW_LO
        ANI 0FH
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        RRC
        JC RPT_ARM
        LDA SW_LO
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        RRC
        RRC
        JC RPT_ARM
        LDA SW_HI
        CPI 00H
        RNZ
RPT_ARM:
        MVI A,0FFH
        STA RPT_STATE
        RET
RPT_RUNNING:
        LDA RPT_STATE
        CPI 09H
        JZ RPT_FINISH
        LDA TX_PENDING
        CPI 00H
        RZ
        MVI A,00H
        STA TX_PENDING
        LDA RPT_STATE
        INR A
        STA RPT_STATE
        CPI 09H
        JZ RPT_HEADER_LINE
        JMP RPT_NEXT_ITEM
RPT_FINISH:
        MVI A,0FEH
        STA RPT_STATE
        RET
RPT_NEXT_ITEM:
        LDA RPT_STATE
        CPI 00H
        JNZ RPT_ITEM_N
        LDA SLOT_FLAGS
        ANI 50H                     ; 'P'
        CPI 50H                     ; 'P'
        RNZ
        LDA SLOT_FLAGS
        JMP RPT_FORMAT
RPT_ITEM_N:
        MOV C,A
        MVI B,00H
        LXI H,SLOT_FLAGS
        DAD B
        MOV A,M
        ANI 0D0H
        CPI 0D0H
        MOV A,M
        RNZ
RPT_FORMAT:
        LDA RPT_STATE
        LXI H,SLOTREC_3
        CALL MUL9_INDEX             ; HL = SLOTREC_3 + 9 * item
        CALL PRT_HEX_HI_SP
        CALL PRT_HEX_BYTE
        LDA RPT_STATE
        CPI 00H
        JNZ RPT_ITEM_OFS
        LXI H,GRI_BCD_HI
        JMP RPT_FMT_TD3
RPT_ITEM_OFS:
        LXI H,7056H                 ; LXI H,7056H: RPT_ITEM_OFS's table base, indexed by MUL10_INDEX
        CALL MUL10_INDEX
RPT_FMT_TD3:
        CALL PRT_TD_DOT
        CALL PRT_HEX_BYTE
        CALL PRT_HEX_BYTE
        LDA RPT_STATE
        CALL GET_ITEM_REC
        MOV A,M
        ANI 20H                     ; ' '
        CPI 00H
        JZ L_1836
        LDA RPT_STATE
        CALL GET_FLAGS_A
        ANI 20H                     ; ' '
        JZ L_1836
        LDA RPT_STATE
        LXI H,M_6FF4
        CALL MUL9_INDEX
        CPI 00H
        MVI A,42H                   ; 'B'
        JNZ L_1838
L_1836:
        MVI A,20H                   ; ' '
L_1838:
        CALL PRTBUF_PUT
        LDA RPT_STATE
        MOV C,A
        MVI B,00H
        LXI H,SLOT_FLAGS
        DAD B
        MOV A,M
        ANI 20H                     ; ' '
        CPI 20H                     ; ' '
        MVI A,4CH                   ; 'L'
        JNZ PRTBUF_PUT
        LDA RPT_STATE
        CALL GET_ITEM_REC
        MOV A,M
        ANI 20H                     ; ' '
        CPI 00H
        MVI A,55H                   ; 'U'
        JZ PRTBUF_PUT
        LDA REC_MASTER
        ANI 20H                     ; ' '
        CPI 00H
        MVI A,4DH                   ; 'M'
        JZ PRTBUF_PUT
        MVI A,20H                   ; ' '

; Print-buffer formatting cluster (186D-19E7), fully decoded this session:
; PRTBUF_PUT (186D): append A to PRTBUF via PRTBUF_PTR (mirrors PRTBUF_GET at 1708).
; NIBBLE_TO_HEX (18B4): low nibble of A -> ASCII hex/BCD digit ('0'-'9','A'-'F').
; BYTE_TO_HEX2 (18AA): byte in A -> two hex chars; falls into NIBBLE_TO_HEX for the low
;   nibble, so on return A = low-nibble char, B = high-nibble char.
; PRT_HEX_BYTE (1878): print byte at (HL) as 2 hex chars (low char first, then high),
;   then HL--; used to format record bytes walking downward through memory.
; PRT_HEX_HI_SP (189B): print ' ' then just the high-nibble hex char of byte at (HL),
;   then HL--; a single-digit field with a leading space.
; PRT_TD_DOT (1885): print ' ', then byte at HL as "lo.hi" (decimal point between the
;   two hex chars), then HL--; used for the first byte of a 3-byte value (RPT_FMT_TD3).
; RPT_FMT_TD3 (1804): PRT_TD_DOT then PRT_HEX_BYTE x2 - formats a 3-byte value ending
;   at HL as ' D.DDDDDD'-shaped text (a TD-style report field). Reached both from
;   RPT_FORMAT (item 0, HL=GRI_BCD_HI) and by falling through RPT_ITEM_OFS's
;   MUL10_INDEX call (other items, HL indexed into the 7056H table).
; PRT_HEX_BYTE_A (197A) / PRT_DIGIT_LO (1984): same idea as PRT_HEX_BYTE/BYTE_TO_HEX2
;   but operate on a value already in A (no HL, no pointer walk): PRT_HEX_BYTE_A prints
;   both hex chars, PRT_DIGIT_LO prints only the low-nibble char (for values that are
;   already a single BCD digit, e.g. SW_D1/SEL_A/SEL_B).
; RPT_HEADER_LINE (1940, xref j17B1, the last REPORT_TASK item): emits LF then CR
;   (printed in that order because PRTBUF drains downward, so they transmit CR,LF), a
;   status digit from BTN_STATE bits 6-7, then SW_D1/SEL_B/SEL_A as single digits and
;   VAR_704F/SW_LO/SW_HI as hex-byte pairs - a header/status line for the report.
PRTBUF_PUT:
        PUSH H
        LHLD PRTBUF_PTR
        MOV M,A
        INX H
        SHLD PRTBUF_PTR
        POP H
        RET
PRT_HEX_BYTE:
        MOV A,M
        CALL BYTE_TO_HEX2
        CALL PRTBUF_PUT
        MOV A,B
        CALL PRTBUF_PUT
        DCX H
        RET
PRT_TD_DOT:
        MVI A,20H                   ; ' '
        CALL PRTBUF_PUT
        MOV A,M
        DCX H
        CALL BYTE_TO_HEX2
        CALL PRTBUF_PUT
        MVI A,2EH                   ; '.'
        CALL PRTBUF_PUT
        MOV A,B
        JMP PRTBUF_PUT
PRT_HEX_HI_SP:
        MVI A,20H                   ; ' '
        CALL PRTBUF_PUT
        MOV A,M
        CALL BYTE_TO_HEX2
        MOV A,B
        CALL PRTBUF_PUT
        DCX H
        RET
BYTE_TO_HEX2:
        MOV C,A
        RRC
        RRC
        RRC
        RRC
        CALL NIBBLE_TO_HEX
        MOV B,A
        MOV A,C
NIBBLE_TO_HEX:
        ANI 0FH
        CPI 0AH
        JM L_18BD
        ADI 07H
L_18BD:
        ADI 30H                     ; '0'
        RET

; TICK_CLOCK_CASCADE: NOT a display refresh (firmware.md's old guess for this
; background task was wrong - fixed there too). Only runs once TICK_BCD wraps to 0.
; Increments VAR_704F (mod 60H BCD), carrying into SW_LO (mod 60H) then SW_HI (mod 24H) -
; an HH:MM:SS-shaped cascading BCD clock in SW_HI:SW_LO:VAR_704F. If STATUS_BITS bit 7
; is clear, also cascades a second HH:MM:SS-shaped clock in VAR_7051:VAR_7050:VAR_70BD.
; Not yet reconciled with SW_LO/SW_HI/VAR_704F's other documented role as latched
; thumbwheel values (front-panel.md) - either these cells are genuinely dual-purpose
; (set-up-mode latch vs. run-mode clock digit), or one of the two roles is misread;
; needs the physical unit's display behavior to settle which.
TICK_CLOCK_CASCADE:
        LDA TICK_BCD
        CPI 00H
        JNZ L_18FE
        LDA VAR_704F
        INR A
        DAA
        CPI 60H                     ; '`'
        STA VAR_704F
        JNZ L_18FE
        MVI A,00H
        STA VAR_704F
        LDA SW_LO
        INR A
        DAA
        CPI 60H                     ; '`'
        STA SW_LO
        JNZ L_18FE
        MVI A,00H
        STA SW_LO
        LDA SW_HI
        INR A
        DAA
        CPI 24H                     ; '$'
        STA SW_HI
        JNZ L_18FE
        MVI A,00H
        STA SW_HI
L_18FE:
        LDA STATUS_BITS
        RLC
        RC
        LDA VAR_70BD
        INR A
        INR A
        DAA
        STA VAR_70BD
        CPI 00H
        RNZ
        LDA VAR_70BE
        INR A
        DAA
        CPI 60H                     ; '`'
        STA VAR_70BE
        RNZ
        MVI A,00H
        STA VAR_70BE
        LDA VAR_7050
        INR A
        DAA
        CPI 60H                     ; '`'
        STA VAR_7050
        RNZ
        MVI A,00H
        STA VAR_7050
        LDA VAR_7051
        INR A
        DAA
        CPI 24H                     ; '$'
        STA VAR_7051
        RNZ
        MVI A,00H
        STA VAR_7051
        RET
RPT_HEADER_LINE:
        MVI A,0AH
        CALL PRTBUF_PUT
        MVI A,0DH
        CALL PRTBUF_PUT
        LDA BTN_STATE
        RLC
        RLC
        ANI 03H
        ORI 30H                     ; '0'
        CALL PRTBUF_PUT
        LDA SW_D1
        CALL PRT_DIGIT_LO
        LDA SEL_B
        CALL PRT_DIGIT_LO
        LDA SEL_A
        CALL PRT_DIGIT_LO
        LDA VAR_704F
        CALL PRT_HEX_BYTE_A
        LDA SW_LO
        CALL PRT_HEX_BYTE_A
        LDA SW_HI
        JMP PRT_HEX_BYTE_A
PRT_HEX_BYTE_A:
        CALL BYTE_TO_HEX2
        CALL PRTBUF_PUT
        MOV A,B
        JMP PRTBUF_PUT
PRT_DIGIT_LO:
        CALL BYTE_TO_HEX2
        JMP PRTBUF_PUT

; ERR_DASH_TBL: 6-byte dash pattern (0AAH,0ABH,0BBH x2) copied by SW_ERR_SHOW's
; loop into M_7034..M_7039 (both display rows); read only via the BC pointer loaded
; at 19BE, never as code. Confirmed purpose: SW_ERR_SEL_A..SW_ERR_GRI4 (1990-19A9)
; are the six switch-validation error stubs named in front-panel.md - each does
; MVI B,<field 1..6> / JMP SW_ERR_SHOW, which fills both display rows with this dash
; pattern, then BCD-formats B into M_7038 and M_7035 (both rows' middle digit) so the
; field number shows through the dashes, e.g. "--N--" over "--N--".
ERR_DASH_TBL:
        DB   0AAH,0ABH,0BBH,0AAH,0ABH,0BBH
SW_ERR_SEL_A:
        MVI B,01H
        JMP SW_ERR_SHOW
SW_ERR_SEL_B:
        MVI B,02H
        JMP SW_ERR_SHOW
SW_ERR_GRI1:
        MVI B,03H
        JMP SW_ERR_SHOW
SW_ERR_GRI2:
        MVI B,04H
        JMP SW_ERR_SHOW
SW_ERR_GRI3:
        MVI B,05H
        JMP SW_ERR_SHOW
SW_ERR_GRI4:
        MVI B,06H
        JMP SW_ERR_SHOW

; Dead code: two more MVI B,nn / JMP SW_ERR_SHOW stubs (nn=07H, then 08H at 19B3)
; continuing the SW_ERR_SEL_A..SW_ERR_GRI4 pattern, but with no callers - READ_SWITCHES
; only validates 6 fields (SEL_A, SEL_B, GRI digits 1-4), so error codes 7 and 8 are
; never raised.
X_19AE:
        DB   06H,07H,0C3H,0B8H,19H
X_19B3:
        DB   06H,08H,0C3H,0B8H,19H

